import dk.zlatan.flotmand.design_system.componenets.spacers.VSpacer
import dk.zlatan.flotmand.design_system.theme.FlotMandTheme
import dk.zlatan.flotmand.model.User

@Composable
fun ProfileScreenRoute(
    modifier: Modifier = Modifier,
    onSignOut: () -> Unit,
    viewModel: ProfileViewModel = hiltViewModel(),
) {
    val user by viewModel.user.collectAsState(initial = User(displayName = "setup name"))
    var sinOutDialogState by remember { mutableStateOf(false) }
    var newDisplayName by remember { mutableStateOf(user.displayName) }
    ProfileScreen(
        modifier = modifier,
        userName = user.displayName,
        onLogoutClicked = {
            sinOutDialogState = true
        },
        onUpdateDisplayNameClick = { newName ->
            viewModel.onUpdateDisplayNameClick(newName)
        }
    )

    if (sinOutDialogState)
    FmAlertDialog(
        onDismiss = {
            sinOutDialogState = false
        },
        onSignOutClick = {
            viewModel.signOut()
        }
    )
}

@Composable
internal fun ProfileScreen(
    modifier: Modifier = Modifier,
    userImage: Int? = null,
    userName: String,
    onUpdateDisplayNameClick: (String) -> Unit,
    onLogoutClicked: () -> Unit = {},
    ) {
    Column(modifier = modifier.fillMaxWidth()) {
        HeaderContainer(
            modifier = Modifier
        ) {
            VSpacer(90.dp)
            ProfileImage(
                modifier = Modifier,
                profilePic = userImage,
                profileSize = 100.dp,
                userName = getInitials(userName)
            )
            VSpacer(20.dp)
            DisplayName(
                displayName = userName,
                onUpdateDisplayNameClick = { updatedName ->
                    onUpdateDisplayNameClick(updatedName)
                }
            )

        }

        VSpacer(24.dp)
        SectionCard(
            title = "Log ud",
            onClick = onLogoutClicked

        )

        Spacer(modifier = Modifier.weight(1f))




    }
}

private fun getInitials(name: String): String {
    return name.split(" ")
        .filter { it.isNotBlank() }
        .map { it.first().uppercaseChar() }
        .joinToString("")
}

@Preview
@Composable
private fun ProfileScreenPreview() {
    FlotMandTheme() {
        ProfileScreen(
            modifier = Modifier,
            userName = "Oliver Payne",
            onUpdateDisplayNameClick = {}
        )
    }
}

